// POST /auth/callback — exchange code, then trust the ID token
async function callback(req, res) {
  const { id_token } = await exchangeCode(req.query.code);

  // decode the JWT and read the claims
  const claims = jwt.decode(id_token); // no signature verification

  const userId = claims.sub;
  const email = claims.email;

  // issuer/audience not checked
  // exp not checked

  const session = await createSession({
    userId,
    email,
    // local session valid for 30 days
    expiresAt: Date.now() + 30 * 24 * 60 * 60 * 1000,
  });
  res.cookie('sid', session.id, { httpOnly: true });
  res.redirect('/dashboard');
}
